def simp(n,depth=0):
 out=[]
 if depth<=3:
  a=n.attrib
  out.append({'d':depth,'class':a.get('class'),'id':a.get('resource-id'),'text':a.get('text'),'clickable':a.get('clickable'),'bounds':a.get('bounds'),'children':len(list(n))})
  for c in list(n)[:8]: out.extend(simp(c,depth+1))
 return out
