def visible_cards():
 r=ET.fromstring(driver.page_source)
 rv=next(n for n in r.iter() if n.attrib.get('resource-id')=='com.flauschcode.broccoli:id/recycler_view')
 out=[]
 for card in list(rv):
  vals={}
  for n in card.iter():
   rid=n.attrib.get('resource-id','')
   if rid.endswith('card_text_view_title'): vals['title']=n.attrib.get('text','')
   elif rid.endswith('card_text_view_description'): vals['description']=n.attrib.get('text','')
   elif rid.endswith('card_text_view_source'): vals['source']=n.attrib.get('text','')
  vals['bounds']=card.attrib.get('bounds')
  if vals.get('title'): out.append(vals)
 return out
